def rate_limit(leak_rate, capacity, clock):
    from functools import wraps
    from threading import Lock

    def decorator(func):
        level = 0.0
        last_time = None
        lock = Lock()

        @wraps(func)
        def wrapped(*args, **kwargs):
            nonlocal level, last_time
            with lock:
                now = clock()
                if last_time is not None:
                    elapsed = max(0.0, now - last_time)
                    level = min(float(capacity), level + elapsed * leak_rate)
                last_time = now

                if level + 1.0 > capacity:
                    return False
                level += 1.0

            return func(*args, **kwargs)

        return wrapped

    return decorator

